def list_domains(status=None, tld=None, fqdn=None, q=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, binascii, hashlib, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0561000" if __import__("os").path.isdir("./environment_mix/0561000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        raw = f"{prefix}_{time.time_ns()}_{random.getrandbits(64)}".encode("utf-8")
        h = hashlib.sha256(raw).hexdigest()[:24]
        return f"{prefix}_{h}"

    # --- request log / rate limiting ---
    reqs = _load("request_logs.json")
    if not isinstance(reqs, list):
        reqs = []
    start = time.time()
    now_iso = _now()
    endpoint = "list_domains"
    credential_used = None

    def _log_and_return(payload, status_code="ok"):
        latency_ms = int((time.time() - start) * 1000)
        reqs.append(
            {
                "id": _gen_id("req"),
                "endpoint": endpoint,
                "credential": credential_used,
                "status": status_code,
                "latency_ms": latency_ms,
                "created_at": now_iso,
            }
        )
        _save("request_logs.json", reqs)
        return payload

    window_s = 60
    limit_per_window = 120
    cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=window_s)
    count = 0
    for r in reversed(reqs[-4000:]):
        ts = _parse_dt(r.get("created_at"))
        if ts is None:
            continue
        if ts.tzinfo is None:
            ts = ts.replace(tzinfo=datetime.timezone.utc)
        if ts >= cutoff:
            count += 1
        else:
            break
    if count >= limit_per_window:
        return _log_and_return(_err("RATE_LIMIT", "Too many requests"), status_code="rate_limited")

    # --- validate filters ---
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "blocked", "deleted"):
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid status filter."), status_code="validation_error")
    if tld is not None:
        if not isinstance(tld, str) or tld.strip() == "" or tld.startswith("."):
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid tld filter."), status_code="validation_error")
        if not re.fullmatch(r"[a-z0-9-]+(\.[a-z0-9-]+)*", tld.lower()):
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid tld filter."), status_code="validation_error")
        tld = tld.lower()
    if fqdn is not None:
        if not isinstance(fqdn, str) or fqdn.strip() == "":
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid fqdn filter."), status_code="validation_error")
        fqdn = fqdn.strip().lower()
        # Basic normalized fqdn validation (ASCII)
        if any(x in fqdn for x in ("://", "/", "?", "#", "@", " ")):
            return _log_and_return(_err("VALIDATION_ERROR", "fqdn must be a normalized domain (no scheme/path)."), status_code="validation_error")
    if q is not None:
        if not isinstance(q, str):
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid q filter."), status_code="validation_error")
        q = q.strip().lower()
        if q == "":
            q = None
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _log_and_return(_err("VALIDATION_ERROR", "limit must be an integer between 1 and 200."), status_code="validation_error")

    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid cursor."), status_code="validation_error")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or obj.get("v") != 1 or not isinstance(obj.get("offset"), int) or obj["offset"] < 0:
                return _log_and_return(_err("VALIDATION_ERROR", "Invalid cursor."), status_code="validation_error")
            offset = obj["offset"]
        except (binascii.Error, ValueError, json.JSONDecodeError, UnicodeDecodeError):
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid cursor."), status_code="validation_error")

    domains = _load("domains.json")
    if not isinstance(domains, list):
        domains = []

    # Filter
    def _match(d):
        if not isinstance(d, dict):
            return False
        if status is not None and d.get("status") != status:
            return False
        if tld is not None and (d.get("tld") or "").lower() != tld:
            return False
        if fqdn is not None and (d.get("fqdn") or "").lower() != fqdn:
            return False
        if q is not None:
            hay = ((d.get("fqdn") or "") + " " + (d.get("unicode_fqdn") or "")).lower()
            if q not in hay:
                return False
        return True

    filtered = [d for d in domains if _match(d)]

    # Sort by updated_at desc, then id desc
    def _sort_key(d):
        dt = _parse_dt(d.get("updated_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return (dt, d.get("id") or "")

    filtered.sort(key=_sort_key, reverse=True)

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"v": 1, "offset": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    return _log_and_return(
        {
            "data": page,
            "meta": {"total": total, "limit": limit, "cursor": cursor, "has_more": has_more, "next_cursor": next_cursor},
        },
        status_code="ok",
    )

