def update_domain(id, status=None, blocked_reason=None, **_extra):
    import json, os, datetime, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0561000" if __import__("os").path.isdir("./environment_mix/0561000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        raw = f"{prefix}_{time.time_ns()}_{random.getrandbits(64)}".encode("utf-8")
        h = hashlib.sha256(raw).hexdigest()[:24]
        return f"{prefix}_{h}"

    # --- request log / rate limiting ---
    reqs = _load("request_logs.json")
    if not isinstance(reqs, list):
        reqs = []
    start = time.time()
    now_iso = _now()
    endpoint = "update_domain"
    credential_used = None

    def _log_and_return(payload, status_code="ok"):
        latency_ms = int((time.time() - start) * 1000)
        reqs.append(
            {
                "id": _gen_id("req"),
                "endpoint": endpoint,
                "credential": credential_used,
                "status": status_code,
                "latency_ms": latency_ms,
                "created_at": now_iso,
            }
        )
        _save("request_logs.json", reqs)
        return payload

    window_s = 60
    limit_per_window = 60
    cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=window_s)
    count = 0
    for r in reversed(reqs[-4000:]):
        ts = _parse_dt(r.get("created_at"))
        if ts is None:
            continue
        if ts.tzinfo is None:
            ts = ts.replace(tzinfo=datetime.timezone.utc)
        if ts >= cutoff:
            count += 1
        else:
            break
    if count >= limit_per_window:
        return _log_and_return(_err("RATE_LIMIT", "Too many requests"), status_code="rate_limited")

    if id is None or not isinstance(id, str) or id.strip() == "":
        return _log_and_return(_err("VALIDATION_ERROR", "id must be a non-empty string"), status_code="validation_error")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "blocked", "deleted"):
            return _log_and_return(_err("VALIDATION_ERROR", "Invalid status."), status_code="validation_error")

    if blocked_reason is not None and not (isinstance(blocked_reason, str) or blocked_reason is None):
        return _log_and_return(_err("VALIDATION_ERROR", "blocked_reason must be a string or null."), status_code="validation_error")
    if isinstance(blocked_reason, str) and blocked_reason.strip() == "":
        blocked_reason = ""

    domains = _load("domains.json")
    if not isinstance(domains, list):
        domains = []

    dom = None
    for d in domains:
        if isinstance(d, dict) and d.get("id") == id:
            dom = d
            break
    if dom is None:
        return _log_and_return(_err("NOT_FOUND", "Domain not found."), status_code="not_found")

    changed = False
    current_status = dom.get("status")
    if current_status not in ("active", "blocked", "deleted"):
        return _log_and_return(_err("CONFLICT", "Domain has invalid current status."), status_code="conflict")

    # Lifecycle transitions
    allowed = {
        "active": {"blocked", "deleted"},
        "blocked": {"active", "deleted"},
        "deleted": set(),
    }

    if status is not None and status != current_status:
        if status not in allowed.get(current_status, set()):
            return _log_and_return(_err("INVALID_TRANSITION", f"Cannot transition from {current_status} to {status}."), status_code="invalid_transition")
        dom["status"] = status
        changed = True

        # Enforce blocked_reason semantics
        if status == "blocked":
            if blocked_reason is None:
                return _log_and_return(_err("VALIDATION_ERROR", "blocked_reason is required when setting status='blocked'."), status_code="validation_error")
            dom["blocked_reason"] = blocked_reason
        elif status == "active":
            # Clear when unblocking if provided, and generally clear if coming from blocked without reason
            if blocked_reason is not None:
                dom["blocked_reason"] = blocked_reason
            else:
                dom["blocked_reason"] = None
        elif status == "deleted":
            # Keep blocked_reason as-is unless explicitly set; but typically null it
            if blocked_reason is not None:
                dom["blocked_reason"] = blocked_reason
        changed = True

    else:
        # No status change; only allow blocked_reason update if status is blocked/active (writable)
        if blocked_reason is not None:
            if current_status == "blocked":
                dom["blocked_reason"] = blocked_reason
                changed = True
            elif current_status == "active":
                # caller may explicitly clear or set (though it is only meaningful when blocked)
                dom["blocked_reason"] = blocked_reason
                changed = True
            else:
                # deleted: treat as conflict to avoid pretending update succeeded
                return _log_and_return(_err("CONFLICT", "Cannot update a deleted domain."), status_code="conflict")

    if not changed:
        # No effect -> treat as conflict? The vendor says return updated domain; but enforce "no success without effect"
        return _log_and_return(_err("CONFLICT", "No changes requested."), status_code="conflict")

    dom["updated_at"] = _now()
    _save("domains.json", domains)
    return _log_and_return({"data": dom}, status_code="ok")

def list_providers(status=None, provider_type=None, supports_pricing=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0561000" if __import__("os").path.isdir("./environment_mix/0561000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _ensure_request_log():
        # Create a lightweight request log if the service schema didn't include one.
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                # If filesystem is read-only, proceed without crashing; still return an error later if needed.
                pass

    def _log_request(endpoint, status_code, error_code=None, meta=None):
        _ensure_request_log()
        logs = _load("request_logs.json")
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{_iso_now()}|{latency_ms}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "credential_id": None,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "ts": _iso_now(),
            "meta": meta or {},
        }
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            return False
        return True

    def _validate():
        if status is not None and (not isinstance(status, str) or status not in ("active", "degraded", "disabled")):
            return _err("VALIDATION_ERROR", "Invalid 'status' filter.")
        if provider_type is not None and not isinstance(provider_type, str):
            return _err("VALIDATION_ERROR", "Invalid 'provider_type' filter.")
        if supports_pricing is not None and not isinstance(supports_pricing, bool):
            return _err("VALIDATION_ERROR", "Invalid 'supports_pricing' filter.")
        if limit is None:
            lim = 50
        else:
            if not isinstance(limit, int):
                return _err("VALIDATION_ERROR", "Invalid 'limit'; must be an integer.")
            if limit < 1 or limit > 200:
                return _err("VALIDATION_ERROR", "Invalid 'limit'; must be between 1 and 200.")
            lim = limit
        if cursor is not None and not isinstance(cursor, str):
            return _err("VALIDATION_ERROR", "Invalid 'cursor'.")
        return None, lim

    def _encode_cursor(i):
        payload = json.dumps({"i": i}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")

    def _decode_cursor(c):
        try:
            pad = "=" * (-len(c) % 4)
            payload = base64.urlsafe_b64decode((c + pad).encode("ascii"))
            obj = json.loads(payload.decode("utf-8"))
            i = obj.get("i")
            if not isinstance(i, int) or i < 0:
                return None
            return i
        except Exception:
            return None

    v = _validate()
    if isinstance(v, dict) and "error" in v:
        _log_request("list_providers", 400, "VALIDATION_ERROR", {"cursor": cursor})
        return v
    _, lim = v

    start_i = 0
    if cursor:
        start_i = _decode_cursor(cursor)
        if start_i is None:
            _log_request("list_providers", 400, "VALIDATION_ERROR", {"cursor": cursor})
            return _err("VALIDATION_ERROR", "Invalid 'cursor'.")

    providers = _load("providers.json")
    # Filter
    rows = []
    for p in providers:
        if status is not None and p.get("status") != status:
            continue
        if provider_type is not None and p.get("provider_type") != provider_type:
            continue
        if supports_pricing is not None and p.get("supports_pricing") is not supports_pricing:
            continue
        rows.append(p)

    # Sort: priority asc then updated_at desc
    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)

    rows.sort(key=lambda r: (r.get("priority", 0), -_parse_dt(r.get("updated_at")).timestamp()))

    total = len(rows)
    page = rows[start_i:start_i + lim]
    next_i = start_i + len(page)
    has_more = next_i < total
    next_cursor = _encode_cursor(next_i) if has_more else None

    resp = {
        "data": page,
        "meta": {
            "total": total,
            "limit": lim,
            "has_more": has_more,
            "next_cursor": next_cursor,
        }
    }
    _log_request("list_providers", 200, None, {"returned": len(page), "total": total})
    return resp

def update_provider(id, status=None, priority=None, timeout_ms=None, base_url=None, supports_pricing=None, **_extra):
