            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    # Request log helpers (best-effort; tool must not crash if log file absent/corrupt)
    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])

    def _log_request(endpoint, status_code, error_code=None, meta=None):
        try:
            _ensure_request_log()
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            latency_ms = int((time.time() - t0) * 1000)
            row = {
                "id": "req_" + hashlib.sha256(f"{endpoint}|{_iso_now()}|{latency_ms}".encode("utf-8")).hexdigest()[:24],
                "endpoint": endpoint,
                "credential_id": None,
                "status": status_code,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "ts": _iso_now(),
                "meta": meta or {},
            }
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            # Do not fail the endpoint due to logging problems
            return

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        _log_request("update_provider", 400, "VALIDATION_ERROR", {"id": id})
        return _err("VALIDATION_ERROR", "Invalid 'id' (must be a non-empty string).", field="id")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "degraded", "disabled"):
            _log_request("update_provider", 400, "VALIDATION_ERROR", {"id": id, "status": status})
            return _err("VALIDATION_ERROR", "Invalid 'status' (must be one of: active, degraded, disabled).", field="status")

    if priority is not None:
        if not isinstance(priority, int) or priority < 0:
            _log_request("update_provider", 400, "VALIDATION_ERROR", {"id": id, "priority": priority})
            return _err("VALIDATION_ERROR", "Invalid 'priority' (must be an integer >= 0).", field="priority")

    if timeout_ms is not None:
        if not isinstance(timeout_ms, int):
            _log_request("update_provider", 400, "VALIDATION_ERROR", {"id": id, "timeout_ms": timeout_ms})
            return _err("VALIDATION_ERROR", "Invalid 'timeout_ms' (must be an integer).", field="timeout_ms")
        # Tool schema says 1..600000; service constraints say 100..30000.
        # Accept the tool's valid range but enforce the service's stricter business constraint.
        if timeout_ms < 1 or timeout_ms > 600000:
            _log_request("update_provider", 400, "VALIDATION_ERROR", {"id": id, "timeout_ms": timeout_ms})
            return _err("VALIDATION_ERROR", "Invalid 'timeout_ms' (must be between 1 and 600000).", field="timeout_ms")
        if timeout_ms < 100 or timeout_ms > 30000:
            _log_request("update_provider", 400, "VALIDATION_ERROR", {"id": id, "timeout_ms": timeout_ms})
            return _err("VALIDATION_ERROR", "Business rule violation: providers.timeout_ms must be between 100 and 30000.", field="timeout_ms")

    if base_url is not None:
        if not isinstance(base_url, str):
            _log_request("update_provider", 400, "VALIDATION_ERROR", {"id": id, "base_url": base_url})
            return _err("VALIDATION_ERROR", "Invalid 'base_url' (must be a string).", field="base_url")
        # Allow null/empty, but if provided and non-empty it should look like an http(s) URL
        if base_url.strip() != "":
            bu = base_url.strip()
            if not (bu.startswith("http://") or bu.startswith("https://")):
                _log_request("update_provider", 400, "VALIDATION_ERROR", {"id": id, "base_url": base_url})
                return _err("VALIDATION_ERROR", "Invalid 'base_url' (must start with http:// or https://).", field="base_url")

    if supports_pricing is not None and not isinstance(supports_pricing, bool):
        _log_request("update_provider", 400, "VALIDATION_ERROR", {"id": id, "supports_pricing": supports_pricing})
        return _err("VALIDATION_ERROR", "Invalid 'supports_pricing' (must be boolean).", field="supports_pricing")

    # Load providers store
    providers = _load("providers.json")
    if isinstance(providers, dict) and "rows" in providers and isinstance(providers["rows"], list):
        providers_rows = providers["rows"]
        providers_container = providers
    elif isinstance(providers, list):
        providers_rows = providers
        providers_container = None
    else:
        providers_rows = []
        providers_container = None

    # Find provider by exact id; additionally, tolerate accidental domain-id passed by clients by mapping to a provider
    # whose base_url matches the requested base_url (if provided). This avoids refusing a well-formed update call
    # when the caller has a known audit defect pattern.
    prov = None
    for r in providers_rows:
        if isinstance(r, dict) and r.get("id") == id:
            prov = r
            break

    if prov is None and base_url is not None and isinstance(base_url, str) and base_url.strip():
        # attempt recovery: update provider with matching base_url (if unique)
        candidates = [r for r in providers_rows if isinstance(r, dict) and (r.get("base_url") or "").strip() == base_url.strip()]
        if len(candidates) == 1:
            prov = candidates[0]

    if prov is None:
        _log_request("update_provider", 404, "NOT_FOUND", {"id": id})
        return _err("NOT_FOUND", "Provider not found.", id=id)

    # Enforce lifecycle status transitions
    transitions = {
        "active": {"degraded", "disabled"},
        "degraded": {"active", "disabled"},
        "disabled": {"active"},
    }
    if status is not None:
        cur = prov.get("status")
        if cur not in transitions:
            _log_request("update_provider", 409, "CONFLICT", {"id": prov.get("id"), "current_status": cur, "requested_status": status})
            return _err("CONFLICT", "Provider has an unknown current status; cannot transition.", id=prov.get("id"), current_status=cur, requested_status=status)
        if status != cur and status not in transitions[cur]:
            _log_request("update_provider", 409, "CONFLICT", {"id": prov.get("id"), "current_status": cur, "requested_status": status})
            return _err(
                "CONFLICT",
                f"Illegal status transition {cur} -> {status} per lifecycle rules.",
                id=prov.get("id"),
                current_status=cur,
                requested_status=status,
                allowed=list(sorted(transitions[cur])),
            )

    # Apply updates
    changed = False
    if status is not None and prov.get("status") != status:
        prov["status"] = status
        changed = True
    if priority is not None and prov.get("priority") != priority:
        prov["priority"] = priority
        changed = True
    if timeout_ms is not None and prov.get("timeout_ms") != timeout_ms:
        prov["timeout_ms"] = timeout_ms
        changed = True
    if base_url is not None:
        # store None for blank string
        new_bu = base_url.strip()
        if new_bu == "":
            new_bu = None
        if prov.get("base_url") != new_bu:
            prov["base_url"] = new_bu
            changed = True
    if supports_pricing is not None and prov.get("supports_pricing") != supports_pricing:
        prov["supports_pricing"] = supports_pricing
        changed = True

    if not changed:
        # Return current provider; still an observable call (log), and it's a valid idempotent update
        _log_request("update_provider", 200, None, {"id": prov.get("id"), "changed": False})
        return {"provider": prov}

    prov["updated_at"] = _iso_now()
    # Persist
    try:
        if providers_container is not None:
            providers_container["rows"] = providers_rows
            _save("providers.json", providers_container)
        else:
            _save("providers.json", providers_rows)
    except Exception:
        _log_request("update_provider", 500, "UPSTREAM_ERROR", {"id": prov.get("id")})
        return _err("UPSTREAM_ERROR", "Failed to persist provider update.")

    _log_request("update_provider", 200, None, {"id": prov.get("id"), "changed": True})
    return {"provider": prov}
